  `last_login_time` timestamp NULL DEFAULT NULL,
  `last_logout_time` timestamp NULL DEFAULT NULL,
  `create_ip` varchar(255) DEFAULT NULL COMMENT '注册IP',
  `last_login_ip` varchar(255) DEFAULT NULL,
  `first_charge_time` timestamp NULL DEFAULT NULL,
  `last_charge_time` timestamp NULL DEFAULT NULL,
  `add_time` timestamp NULL DEFAULT NULL,
  `modify_time` timestamp NULL DEFAULT NULL,
  `activ_special_skill` varchar(255) DEFAULT NULL,
  `offline_time` bigint(20) DEFAULT NULL,
  `fang_chenmi` int(11) DEFAULT NULL,
  `chenmi_online_time` int(11) DEFAULT NULL,
  `chenmi_offline_time` int(11) DEFAULT NULL,
  `online_millis` bigint(20) DEFAULT NULL COMMENT '角色在线时长总和',
  `update_millis` bigint(20) DEFAULT NULL COMMENT '距离上一次升级在线时长总和',
  `gunfu` int(11) DEFAULT NULL COMMENT '是不是滚服',
  `jinyan_expireTime` timestamp NULL DEFAULT NULL COMMENT '禁言失效时间',
  `fenghao_expireTime` timestamp NULL DEFAULT NULL COMMENT '封号失效时间',
  `pre_name` text COMMENT '曾用名',
  `is_3d` tinyint(1) DEFAULT '1' COMMENT '是不是3d创建角色界面',
  `online_time_all` bigint(20) DEFAULT NULL COMMENT '累计在线时长',
  `power` bigint(20) DEFAULT NULL COMMENT '战力',
  `gm_yy` int(11) DEFAULT NULL COMMENT '是不是yy福利系统的内部人员,1是',
  `log_update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`),
  UNIQUE KEY `INDEX_UN_role_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

